  /* egyensúly: a nehéz ütések megingatják a főellenséget – ilyenkor másfélszer sebződik */
  if (B && e.st !== 'stun' && e.hp > 0) { e.pos = (e.pos || 0) + (crit ? 24 : 9); if (e.pos >= 100) { e.pos = 0; e.st = 'stun'; e.tm = 2.3; e.mode = null; fxNum(e.x, e.y - 96, 'MEGINGOTT', '#ffd35a', 1); sfx(160, .4, 'square', .07, -90); CAM.sh = 12; } }
  if (e.st === 'idle' || e.st === 'back') { e.st = 'chase'; } if (!B && (e.st === 'wind' || e.st === 'chase')) { e.st = 'hurt'; e.tm = .22; }
