function interact() { const t = target(); if (!t) return; if (t.npc) return npcTalk(t.npc.id); const o = t.o, f = P.f, d = DRY();
  if (o.t === 'fire') { let nw = 0; const dry = o.i === 2 && d >= 8 && !P.fin; if (!dry) { P.hp = P.mhp; P.mp = P.mmp; P.pot = Math.max(P.pot, P.fl); } if (o.i >= 0) { P.fire = o.i; if (!P.fires[o.i]) { P.fires[o.i] = 1; nw = 1; } } spawnAll(); save(); banner(nw ? 'KÚT MEGTALÁLVA' : dry ? 'A KÚT MÁR NEM GYÓGYÍT' : 'MEGPIHENTÉL A KÚTNÁL', nw ? FIRE_N[o.i] : dry ? '' : 'A Kiszáradtak visszatértek', 2.4); sfx(330, .5, 'sine', .06, 200); FX.push({ k: 'ring', x: o.x, y: o.y, l: .8, r: 140, col: '120,200,255' }); ST = 'rest'; }
  else if (o.t === 'msg') talk('Kőbe vésett sorok', [o.txt]);
  else if (o.t === 'page') { P.pg[o.i] = 1; save(); sfx(700, .3, 'triangle', .05, 200); talk(`Szilárd naplója · ${o.i + 1}. lap  (${pages()}/12)`, [o.txt]); }
  else if (o.t === 'dew') { const c0 = 250; if (P.gold < c0) return say(`Harmatgyűjtő állomás: ${c0} Harmat kell hozzá.`); P.gold -= c0; P.dw[o.i] = 1; save(); banner('HARMATGYŰJTŐ ÁLLOMÁS', dews() + ' a nyolcból', 2.6); sfx(520, .4, 'triangle', .06, 300); }
  else if (o.t === 'door') { if (o.big && !o.out && d < 8) return talk('A Királyi Kút', ['Kiszáradt, végtelen mély akna. A fala mentén lépcső indul lefelé, de pár fok után elnyeli a sötét.', `Nyolc szilánk fénye kellene, hogy lásd. Nálad ${d} van.`]); enter(o); }
  else if (o.t === 'box') { f.gyula = 1; save(); talk('', ['A sorsolóláda alja dupla. Minden golyón ugyanaz a név áll: Gyula.', 'A falu népe köréd gyűlik. Senki nem kiabál. Elviszik.']); }
  else if (o.t === 'belltree') { sfx(196, 2.2, 'sine', .09, -6); sfx(392, 1.8, 'sine', .04, -10); o.rung = T; say(P.f.harang ? 'A harang zúg. Északról egy másik felel rá.' : 'Megkongatod. Az erdő elhallgat.'); }
  else if (o.t === 'heart') talk('A Forrás Szíve', ['Hatalmas, fehér kő. Ráteszed a tenyered.', 'Még dobog. Nagyon halkan.', 'A kilencedik foglalat üres, a széle olvadt – mintha valami kiszakította volna.']);
  else if (o.t === 'chest') { P.chest[o.id] = 1; const w = biomeW(o.x, o.y), tr = w.z ? w.z.t : RK[w.k].t, q = rnd(o.x, o.y, 77), sp = { c1: 'w1', c7: 'w2', c13: 'viz', zroncs: 'terkep', c15: 'olaj', c16: 'olaj', zsobanya: 'olaj', zkollegium: 'seed', zmagtar: 'seed', zcsepego: 'seed' }[o.id], g = 60 + tr * 70; for (let i = 0; i < 8; i++) drop('gold', o.x, o.y, Math.ceil(g / 8)); if (q < .5) drop('pot', o.x, o.y, 1);
    if (sp) give(sp); else if (o.id[0] === 'z') give(q < .5 ? 'seed' : 'ore'); else if (q > .82) give('seed'); else if (q > .5) give('ore'); if (o.id[0] === 'z') give('ore'); sfx(600, .3, 'triangle', .06, 400); save(); } }
function target() { let b = null, bd = 78; for (const n of NPCS) { if (!npcOn(n)) continue; const d = hyp(n.x - P.x, n.y - P.y); if (d < bd) { bd = d; b = { npc: n, x: n.x, y: n.y - 70 }; } }
  near(P.x, P.y, 130, o => { const t = o.t; if (t !== 'fire' && t !== 'chest' && t !== 'msg' && t !== 'page' && t !== 'dew' && t !== 'door' && t !== 'box' && t !== 'belltree' && t !== 'heart') return; if (bossOn) return; if (t === 'chest' && P.chest[o.id]) return; if (t === 'page' && P.pg[o.i]) return; if (t === 'dew' && P.dw[o.i]) return; if (t === 'box' && P.f.gyula) return;
    const d = hyp(o.x - P.x, o.y - P.y) - (t === 'door' || t === 'heart' ? 40 : 0); if ((t === 'msg' || t === 'page') && d > 46) return; if (d < bd) { bd = d; b = { o, x: o.x, y: o.y - (t === 'msg' ? 34 : t === 'page' ? 44 : t === 'heart' ? 120 : t === 'door' ? (o.up ? 160 : 66) : t === 'belltree' ? 130 : 80) }; } }); return b; }
const QPOS = () => { const d = DRY(), z = zoneAt(P.x, P.y); if (z && !z.open) return null; if (!P.f.erzs) return HUB; if (P.fin) return null; if (d < 8) { const k = LORDS.find(k => !P.sh[k]); return z ? null : LORD[k]; } return z && z.open ? HEART : z ? null : KWELL; };
const QTXT = () => { if (!P.f.erzs) return 'Keresd meg az Utolsó Kutat, nyugatra az úton'; if (P.fin) return 'Ázottföld vár. ' + ENDS[P.fin][0][0] + ENDS[P.fin][0].slice(1).toLowerCase() + '.'; const d = DRY(); if (d < 8) return `Forrásszilánkok: ${d} / 8  ·  ${ET[LORDS.find(k => !P.sh[k])].n}`; return zoneAt(P.x, P.y) ? 'A Forrás Szíve · Szikkadt Szilárd' : 'Ereszkedj le a Királyi Kúton, Szárazvár közepén'; };

